> > +/*** V4L2 ***/
> > +
> > +static int rkisp2_params_enum_fmt_meta_out(struct file *file, void *fh,
> > +                                        struct v4l2_fmtdesc *f)
> > +{
> > +     if (f->index)
> > +             return -EINVAL;
> > +
> > +     if (f->mbus_code && f->mbus_code != MEDIA_BUS_FMT_METADATA_FIXED)
> > +             return -EINVAL;
> > +
